api/ajouter-un-document-à-un-objet.html.description:
Cette API permet, depuis une application tierce, d'ajouter une pièce jointe à un objet (échantillon, contenant). L'API autorise soit le téléchargement d'un nouveau fichier, soit le référencement d'un fichier si la collection autorise le stockage externe des documents.Consultez ce document pour créer l'utilisateur de l'API, générer un token et lui donner les droits adéquats : <a data-href="Identification pour les API" href="api/identification-pour-les-api.html" class="internal-link" target="_self" rel="noopener nofollow">Identification pour les API</a>
URL : apiv1documentWrite
L'API doit être appelée en mode http POST.Si vous renseignez la variable external_storage_path, le fichier cible doit exister dans l'arborescence externe et être accessible au serveur web.Voici un exemple d'envoi d'un fichier vers le serveur, écrit en PHP :&lt;?php
$address = "https://monsite.collec-science.org";
$params = [ "login" =&gt; "compteapi", "token" =&gt; "SECRET", "uid" =&gt; 1234
];
$fileToSend = "/home/equinton/Images/eel.jpg";
$method = "POST";
$debugMode = false;
class ApiCurlException extends Exception {};
function makeCurlFile($file)
{ $mime = mime_content_type($file); $info = pathinfo($file); $name = $info['basename']; $output = new CURLFile($file, $mime, $name); return $output;
}
function apiCall($method, $url, $certificate_path = "", $data = array(), $modeDebug = false, $file = "")
{ $curl = curl_init($url); if (!$curl) { throw new ApiCurlException(_("Impossible d'initialiser le composant curl")); } if (!empty($file)) { $data["file"] = makeCurlFile($file); } switch ($method) { case "POST": curl_setopt($curl, CURLOPT_POST, true); if (!empty($data)) { curl_setopt($curl, CURLOPT_POSTFIELDS, $data); } break; case "PUT": curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "PUT"); if (!empty($data)) { curl_setopt($curl, CURLOPT_POSTFIELDS, $data); } break; default: if (!empty($data)) { $url = sprintf("%s?%s", $url, http_build_query($data)); echo "URL: $url" . PHP_EOL; } } /** * Set options */ curl_setopt($curl, CURLOPT_URL, $url); curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1); if (!empty($certificate_path)) { curl_setopt($curl, CURLOPT_SSLCERT, $certificate_path); } curl_setopt($curl, CURLOPT_SSL_VERIFYSTATUS, false); curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0); if ($modeDebug) { curl_setopt($curl, CURLOPT_VERBOSE, true); } /** * Execute request */ $res = curl_exec($curl); if ($res === false) { throw new ApiCurlException( sprintf( _("Une erreur est survenue lors de l'exécution de la requête vers le serveur distant. Code d'erreur CURL : %s"), curl_error($curl) ) ); } curl_close($curl); return $res;
}
echo "Méthode : " . $method . PHP_EOL;
echo "Adresse : " . $address . "/" . $page . PHP_EOL;
echo "Paramètres" . PHP_EOL;
print_r($params); $res = apiCall($method, $address . "/" . $page, "", $params, $debugMode, $fileToSend);
if ($res == "null") { echo "résultat : null" . PHP_EOL;
} else { if ($page == "apiv1documentGet") { file_put_contents("test.txt", $res); } else { print_r(json_decode($res, true)); }
}
Ce script est prévu pour s'exécuter en ligne de commande :php testapi.php

api/script-pour-appeler-une-api.html.description:
&lt;?php /** * Script to send an API request to Collec-Science server * * To use it: * fill in the variables method, address, page, login, token and params * * execute the script in a terminal, with the command: * php api.php */ /** * generic variables */
$method = "GET"; // or POST
$address = "https://localhost"; // address of the server
$login = "apilogin"; // login used to send api request
$token = "xxx" ; // Token associated with the login
$page = "apiv1sampleList"; // API to request
/** * List of usable pages: * apiv1sampleList (GET) * apiv1sampleUids (GET) * apiv1sampleDisplay (GET) * apiv1sampleDelete (POST) * apiv1movementWrite (POST) * apiv1documents (GET) * apiv1documentGet (GET) * apiv1documentWrite (POST) */ $fileToSend = ""; // location of the file to send (apiv1documentWrite)
/** * List of variables to send to the server. * Except if a collection is public, only 2 variables are mandatory: login and token, * to identify the sender */
$params = [ "login" =&gt;$login, "token"=&gt; $token, /* "uid" =&gt; 1234, collection_id = 1, ... */
];
$debugMode = false; // set to true to see the exchange between curl and the server /** * Functions used by the script */
function is_cli(): bool
{ if (in_array(PHP_SAPI, ['cli', 'phpdbg'], true)) { return true; } return ! isset($_SERVER['REMOTE_ADDR']) &amp;&amp; ! isset($_SERVER['REQUEST_METHOD']);
}
/** * Method printA * * Display the content of a variable (array or not) * * @param any $arr variable to display * @param int $level deepth of interrogation * @param array $exclude list of keys to not display (if array) * * @return void */
function printA($arr, $level = 0, $exclude = array())
{ $childLevel = $level + 1; $nl = getLineFeed(); if (is_array($arr)) { foreach ($arr as $key =&gt; $var) { if (!in_array($key, $exclude)) { if (is_object($var)) { $var = (array) $var; $key .= " (object)"; } for ($i = 0; $i &lt; $level * 4; $i++) { echo "&amp;nbsp;"; } echo $key . ": "; if (is_array($var)) { echo $nl; printA($var, $childLevel, $exclude); } else { print_r($var); echo $nl; } } } } else { echo "$arr" . $nl; }
} /** * Method getLineFeed * * get the end of the line according to context * * @return void */
function getLineFeed()
{ if (is_cli()) { return PHP_EOL; } else { return "&lt;br&gt;"; }
} class ApiCurlException extends Exception {};
/** * Method makeCurlFile used to send a file (apiv1documentWrite) * * @param string $file: path of the file to send * * @return void */
function makeCurlFile($file)
{ $mime = mime_content_type($file); $info = pathinfo($file); $name = $info['basename']; $output = new CURLFile($file, $mime, $name); return $output;
}
/** * call an api with curl * code from * @param string $method * @param string $url * @param array $data */
function apiCall($method, $url, $certificate_path = "", $data = array(), $modeDebug = false, $file = "")
{ $curl = curl_init($url); if (!$curl) { throw new ApiCurlException(_("Impossible d'initialiser le composant curl")); } if (!empty($file)) { $data["file"] = makeCurlFile($file); } switch ($method) { case "POST": curl_setopt($curl, CURLOPT_POST, true); if (!empty($data)) { curl_setopt($curl, CURLOPT_POSTFIELDS, $data); } break; case "PUT": curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "PUT"); if (!empty($data)) { curl_setopt($curl, CURLOPT_POSTFIELDS, $data); } break; default: if (!empty($data)) { $url = sprintf("%s?%s", $url, http_build_query($data)); echo "URL: $url" . PHP_EOL; } } /** * Set options */ curl_setopt($curl, CURLOPT_URL, $url); curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1); if (!empty($certificate_path)) { curl_setopt($curl, CURLOPT_SSLCERT, $certificate_path); } curl_setopt($curl, CURLOPT_SSL_VERIFYSTATUS, false); curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0); if ($modeDebug) { curl_setopt($curl, CURLOPT_VERBOSE, true); } /** * Execute request */ $res = curl_exec($curl); if ($res === false) { throw new ApiCurlException( sprintf( "Une erreur est survenue lors de l'exécution de la requête vers le serveur distant. Code d'erreur CURL : %s", curl_error($curl) ) ); } curl_close($curl); return $res;
} /** * Execution of the api call */
echo "Méthode : " . $method . PHP_EOL;
echo "Adresse : " . $address . "/" . $page . PHP_EOL;
echo "Paramètres :" . PHP_EOL;
printA($params);
$res = apiCall($method, $address . "/" . $page, "", $params, $debugMode, $fileToSend);
if ($res == "null") { echo "résultat : null" . PHP_EOL;
} else { if ($page == "apiv1documentGet") { file_put_contents("test.txt", $res); } else { printA(json_decode($res, true)); }
}

gestion/chercher-les-échantillons.html.description:
Le module permettant de rechercher les échantillons est probablement celui que vous utiliserez le plus dans le logiciel : c'est la porte d'entrée pour accéder à vos échantillons.L'interface est organisé en trois parties : la partie haute permet de définir les critères de recherche ;
la partie centrale affiche la liste des échantillons (ou la carte de leurs emplacements), et permet de réaliser quelques opérations sur ceux-ci, comme l'impression d'étiquettes ou l'export des données ;
la partie basse, accessible si vous disposez du droit "collection" (cf. <a data-href="Les différents types de droits" href="droits/les-différents-types-de-droits.html" class="internal-link" target="_self" rel="noopener nofollow">Les différents types de droits</a>), permet de réaliser des opérations sur plusieurs échantillons à la fois. Ces opérations sont décrites ici : <a data-href="Les opérations globales sur les échantillons" href="objets/les-opérations-globales-sur-les-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">Les opérations globales sur les échantillons</a>.
Les critères de recherche sont cumulatifs, c'est à dire qu'ils s'additionnent les uns aux autres. Ils sont organisés en onglets, pour faciliter leur manipulation :
UID/Identifiant : critères de recherche par nom, collection, statut
Types et métadonnées : recherche sur le type d'échantillon ou par contenu de métadonnée
Dates : recherches sur des créneaux de dates, pour les différents types de dates manipulées
Divers : autres critères de recherche, comme la campagne de prélèvement, le motif de déstockage, le type d'événement, etc.
Localisation : recherche soit par lieu de prélèvement, par pays, ou en sélectionnant une zone sur la carte.
Enfin, un dernier onglet permet d'enregistrer une recherche pour pouvoir la rejouer sans être obligé de repositionner tous les critères.Dans cet interface, quelques informations vont influer sur le comportement global de l'affichage. Il s'agit de la dernière ligne de celui-ci :<br><img alt="Pasted image 20260216100120.png" src="attachments/pasted-image-20260216100120.png" target="_self"> nombre maxi à lire depuis la base de données / À partir de la page : dès lors que votre recherche risque de récupérer plus de quelques centaines d'échantillons, il est fortement conseillé de limiter le nombre renvoyé au navigateur, sous peine d'avoir des temps d'affichage qui augmentent considérablement.
Si vous indiquez une valeur supérieure à 0, les échantillons seront affichés du plus récent au plus ancien (date de création dans la base de données), et vous pourrez naviguer dans les pages. Une fois la requête lancée, le nombre total d'échantillons qui répondent à celle-ci, indépendamment du nombre maxi que vous souhaitez récupéré, sera affiché :<br>
<img alt="Pasted image 20260216100712.png" src="attachments/pasted-image-20260216100712.png" target="_self"> Bouton Rechercher : il va déclencher la recherche, à condition qu'un critère au moins ait été renseigné, pour éviter que la requête vous renvoie tous les échantillons. Bouton RAZ : il réinitialise l'ensemble des critères de recherche à la valeur par défaut. Les critères que vous avez sélectionné sont conservés tout au long de votre session de travail : tant que vous ne vous serez pas déconnecté (ou avez été déconnecté en cas d'inaction prolongée), les critères seront appliqués automatiquement quand vous afficherez cette page de recherche. Bouton Export CSV direct : si vous souhaitez récupérer une liste très conséquente d'échantillons, vous pouvez alors indiquer 0 dans la zone Nombre maxi à lire, et utiliser ce bouton pour récupérer un fichier CSV contenant l'ensemble des informations. C'est le seul moyen pour récupérer rapidement une liste très importante d'échantillons (plusieurs milliers). Activer la recherche par colonne : cette case va changer l'affichage de la liste, en remplaçant les entêtes des colonnes par des zones de saisie. Ces zones vont pouvoir être utilisées pour réaliser des recherches uniquement dans les colonnes considérées.<br>
Pour plus d'informations sur cette fonctionnalité, consultez la page <a data-href="La liste des échantillons" href="gestion/la-liste-des-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">La liste des échantillons</a>. <br><img alt="Pasted image 20260216101353.png" src="attachments/pasted-image-20260216101353.png" target="_self">Pour rechercher par UID, vous avez deux possibilités :
soit vous connaissez l'UID précisément : il suffit de l'indiquer dans la zone UID
soit vous souhaitez rechercher dans une fourchette : il suffit d'indiquer une valeur basse et une valeur haute dans la zone UID entre.
La zone identifiants ou UUID vous permet de rechercher à partir de l'identifiant métier ou de l'UUID de l'échantillon :
en indiquant l'identifiant métier, la recherche va être de type plein texte, c'est à dire que le libellé bx10 ramènera aussi bien bx10-12 que acbx1000, par exemple ;
la recherche est indépendante de la casse : vous pouvez saisir aussi bien BX10 que bx10 ;
si la longueur que vous saisissez dans cette zone est de 36 caractères, la recherche sera réalisée en cherchant l'UUID correspondant.
Si une douchette est connectée à votre ordinateur, vous pouvez également scanner un QRCODE (après avoir positionné le curseur dans cette zone) : le programme extraira alors automatiquement l'identifiant métier de l'étiquette.Vous disposez de deux possibilités pour rechercher par collection :
soit vous sélectionnez une seule collection, dans la liste Collection ;
soit vous pouvez rechercher dans plusieurs collections, en en sélectionnant plusieurs (ctrl + clic souris) dans la zone recherche multiple.
<br>Attention : seules les recherches effectuées à partir de la zone Collection ouvrent la possibilité de réaliser certaines opérations de groupe (cf. <a data-href="Les opérations globales sur les échantillons" href="objets/les-opérations-globales-sur-les-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">Les opérations globales sur les échantillons</a>).Par défaut, la recherche s'effectue uniquement en recherchant les échantillons qui sont dans un état normal. Si vous ne retrouvez pas un échantillon, c'est peut-être que son statut a évolué (échantillon prêté, par exemple) : désactivez alors la recherche par statut pour le retrouver.Collec-Science dispose d'un mécanisme de corbeille : avant de supprimer définitivement un échantillon, vous pouvez simplement le mettre dans une corbeille.Pour retrouver les échantillons mis à la corbeille, désactivez le paramètre En attente de suppression ou indiquez la valeur oui.<br><img alt="Pasted image 20260216103605.png" src="attachments/pasted-image-20260216103605.png" target="_self">À partir de cet onglet, vous pouvez rechercher par type d'échantillon.<br>Si vous n'indiquez pas de type, vous pourrez rechercher dans l'ensemble des métadonnées indiquées comme étant utilisables pour la recherche (cf. <a data-href="Les métadonnées" href="objets/les-métadonnées.html" class="internal-link" target="_self" rel="noopener nofollow">Les métadonnées</a>). Si vous indiquez un type, seules les métadonnées associées à ce type seront proposées dans la zone Rechercher dans les métadonnées. La recherche est une recherche plein texte : si vous indiquez alosa, le programme recherchera indifféremment alosa sp., alosa fallax, etc. Le programme ne tient également pas compte de la casse.Vous pouvez indiquer plusieurs valeurs à rechercher pour la même métadonnée (critère ou), en les séparant par une virgule. Dans l'exemple ci-dessus, le programme recherchera les échantillons dont la métadonnée taxon contient soit le libellé alosa, soit le libellé sturio.Enfin, en cliquant sur l'icone plus, vous pourrez afficher jusqu'à deux lignes supplémentaires de recherche sur les métadonnées, ce qui vous permettra de compléter vos critères en sélectionnant une seconde métadonnée dans les échantillons. Cette recherche est cumulative : seuls les échantillons qui contiennent les deux (ou trois) métadonnées recherchées seront sélectionnés.<br>Cet onglet permet également de limiter l'affichage des métadonnées dans la liste. En sélectionnant une métadonnée dans la liste N'afficher qu'une métadonnée, seule cette métadonnée sera affichée dans la liste des échantillons (cf. <a data-href="La liste des échantillons" href="gestion/la-liste-des-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">La liste des échantillons</a>).<br><img alt="Pasted image 20260216104544.png" src="attachments/pasted-image-20260216104544.png" target="_self">L'onglet Dates va vous permettre de rechercher les échantillons selon plusieurs dates :
la date de création dans la base : c'est la date technique qui correspond à l'ajout de l'échantillon dans la base de données ;
la date d'échantillonnage : c'est la date à laquelle l'échantillon a été récolté ;
la date d'expiration : si vous avez indiqué une date à laquelle l'échantillon n'est plus utilisable, vous pouvez utiliser cette possibilité ;
la date technique de dernier changement : c'est la date où l'échantillon a été modifié pour la dernière fois dans la base de données.
Vous pouvez indiquer une fourchette de temps pour la recherche. Par défaut, celle-ci est positionnée sur une année.Si vous utilisez le module de réservation des échantillons, vous avez également la possibilité de rechercher les échantillons réservés (ou non) sur une période.<br><img alt="Pasted image 20260216105112.png" src="attachments/pasted-image-20260216105112.png" target="_self">À partir de cet onglet, vous pouvez rechercher :
les échantillons "appartenant" à un référent ;
les échantillons qui n'ont pas été rangés dans un contenant (Échantillons sans contenants) ;
ceux qui ont été récoltés pendant une campagne de prélèvement, ou ceux qui ont bénéficié d'une autorisation administrative (N° d'autorisation). La recherche par numéro d'autorisation s'effectue indépendamment des campagnes de prélèvement auxquelles elles sont rattachées ;
ceux qui ont été déstockés pour un motif particulier (Motif de déstockage) ;
enfin, pour les échantillons pour lesquels vous avez activé le sous-échantillonnage, vous pouvez rechercher ceux qui disposent encore d'une certaine quantité (quantité minimale disponible dans l'échantillon) ou ceux qui sont quasiment vides (maximale).
<br><img alt="Pasted image 20260216105730.png" src="attachments/pasted-image-20260216105730.png" target="_self">Cet onglet va permettre deux types de recherche : une recherche sur des critères "classiques", et une recherche par emplacement géographique<br>Vous pouvez lancer une recherche par lieu de prélèvement (cf. <a data-href="Les lieux de prélèvement" href="parametres/les-lieux-de-prélèvement.html" class="internal-link" target="_self" rel="noopener nofollow">Les lieux de prélèvement</a>), par pays de collecte ou par pays de provenance : ces deux dernières informations sont utilisées dans le cadre du protocole de Nagoya (<a rel="noopener nofollow" class="external-link is-unresolved" href="https://fr.wikipedia.org/wiki/Protocole_de_Nagoya" target="_self">https://fr.wikipedia.org/wiki/Protocole_de_Nagoya</a>).Si vous avez indiqué des coordonnées géographiques dans vos échantillons, vous pouvez également lancer la recherche sur une zone particulière. Pour cela, dans la carte, cliquez sur le bouton au centre (à gauche), puis tracez un rectangle sur la carte. Seuls les échantillons présents dans cette zone seront affichés.<br><img alt="Pasted image 20260216110700.png" src="attachments/pasted-image-20260216110700.png" target="_self">Si vous utilisez régulièrement les mêmes critères de recherche et qu'ils sont nombreux à positionner, vous avez la possibilité d'enregistrer ces critères une bonne fois pour toute, à partir de cet onglet.Pour créer une nouvelle recherche enregistrée :
sélectionnez l'ensemble des critères de recherche que vous voulez appliquer ;
indiquez le nom que vous souhaitez donner à votre recherche dans la zone Nom de la recherche.
Quand vous déclencherez la recherche, avec le bouton Rechercher, les critères seront enregistrés.Les recherches sont personnelles, mais vous pouvez toutefois mettre à disposition une recherche pour vos collègues :
dans les critères de recherche, indiquez la collection sur laquelle vous travaillez ;
indiquez le nom de la recherche ;
cliquez sur oui dans la zone Enregistrer pour la collection sélectionnée.
Vos collègues, dès lors qu'ils disposent des droits de modification sur la collection considérée, pourront accéder à la recherche que vous avez enregistré.Pour supprimer une recherche enregistrée, sélectionnez-là dans la liste, puis cliquez sur le bouton Supprimer. La recherche va être lancée, mais elle sera quand même supprimée de la base de données.Si vous souhaitez modifier une recherche enregistrée, vous devrez en créer une nouvelle puis supprimer l'ancienne.La liste des échantillons sélectionnés est affichable sous deux formes :
<br>soit une liste textuelle, décrite ici : <a data-href="La liste des échantillons" href="gestion/la-liste-des-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">La liste des échantillons</a>
soit sous forme de carte géographique, où vous pouvez consulter l'emplacement de chaque échantillon géo-référencé. Pour visualiser l'emplacement des échantillons, sélectionnez l'onglet Carte. Si la densité d'échantillons est trop importante, un cercle sera affiché qui permettra de savoir combien d'échantillons sont situés à cet emplacement.En cliquant sur l'icône d'un échantillon, une bulle s'affiche avec son UID et son identifiant métier. En cliquant sur ces informations, vous ouvrirez le détail de l'échantillon.<br><img alt="Pasted image 20260206112950.png" src="attachments/pasted-image-20260206112950.png" target="_self">Sur la carte, en cliquant sur l'icône &lt;flèche vers le bas&gt;, vous pourrez obtenir une image de la carte, au format paysage. L'image est calculée à partir du centre de la carte.<br>Consultez cette page pour en savoir plus sur les opérations globales possibles : <a data-href="Les opérations globales sur les échantillons" href="objets/les-opérations-globales-sur-les-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">Les opérations globales sur les échantillons</a>

gestion/générer-le-modèle-pour-les-impor.description:
L'importation de masse (<a data-href="L'import de masse" href="gestion/l'import-de-masse.html" class="internal-link" target="_self" rel="noopener nofollow">L'import de masse</a>) permet d'insérer des contenants ou des échantillons dans la base de données à partir d'un fichier CSV. Des contraintes fortes sont imposées concernant la structure de ce fichier, les colonnes doivent respecter une nomenclature, les informations relatives aux objets intégrés (type de contenant ou d'échantillon, collection de destination, etc.) doivent être conformes à ce qui existe dans la base de données.Pour faciliter la création de ce fichier, un module a été ajouté à l'application (à partir de la version v26.1.0). Il permet de générer le canevas de ce fichier, en tenant compte des informations que vous souhaitez intégrer. En particulier, dans le cas de l'importation d'échantillons, les colonnes correspondant aux métadonnées associées aux types d'échantillons sélectionnés seront automatiquement ajoutées.Enfin, au delà de l'entête des colonnes, des lignes d'exemple sont ajoutées, pour faciliter le remplissage du fichier.Ouvrez la page depuis le menu Imports/exports &gt; Modèle d'import de masse :<br><img alt="Pasted image 20260325104100.png" src="attachments/pasted-image-20260325104100.png" target="_self">Vous pourrez décider d'importer des contenants, des échantillons où les deux à la fois.Cochez Importer des contenants. Vous pourrez alors indiquer :
la collection de destination, si le contenant est exclusivement attaché à une collection. Cette information ne sert que pour retrouver les contenants plus facilement ;
le type de contenant (à partir de la famille) : il vous permettra d'avoir le bon libellé dans la ligne d'exemple qui sera générée, mais vous pourrez bien évidemment renseigner n'importe quel type par la suite ;
si vous souhaitez ranger les contenants dans d'autres contenants : dans ce cas, les colonnes container_parent_identifier, container_column et container_line seront rajoutées au fichier ;
si vous voulez décrire les contenants avec la colonne container_comment ;
<br>si vous disposez déjà d'un identifiant de type <a href=".?query=tag:UUID" class="tag is-unresolved" target="_self" rel="noopener nofollow" data-href="#UUID">#UUID</a> pour vos contenants (générés en principe à partir d'une autre application).
<br>N'oubliez pas d'indiquer les identifiants secondaires si nécessaire (cf. <a data-href="#Rajouter des identifiants secondaires" href="gestion/générer-le-modèle-pour-les-importations-de-masse.html#Rajouter_des_identifiants_secondaires_0" class="internal-link" target="_self" rel="noopener nofollow">Rajouter des identifiants secondaires</a>, ci-dessous).Dans le modèle, une ligne d'exemple, prenant en compte le type de contenant, sera généré.Cochez Importer des échantillons. Vous pourrez alors indiquer :<br><img alt="Pasted image 20260328154502.png" src="attachments/pasted-image-20260328154502.png" target="_self">
la collection de destination. Si l'information est obligatoire, rien ne vous empêche de la modifier ensuite quand vous remplirez le fichier ;
le ou les types d'échantillons visés. C'est une information essentielle pour préparer le fichier ! En effet, en fonction des types d'échantillons, les colonnes de métadonnées correspondantes seront rajoutées. Si vous n'indiquez pas de type d'échantillon, aucune colonne ne sera ajoutée pour permettre l'importation d'un échantillon.
le référent, qui sera proposé, dans les lignes d'exemple, sous la forme Nom prénom.
les pays de collecte et de provenance, informations utiles si vos échantillons sont soumis au protocole de Nagoya ;
la campagne de prélèvement, si besoin était ;
le lieu de prélèvement ;
d'autres colonnes supplémentaires peuvent être ajoutées : la date d'expiration de l'échantillon, qui devra être renseignée sous la forme jj/mm/aaaa ;
l'identifiant dans la base de données d'origine. En principe, cet identifiant doit être construit sous la forme sigle:numéro, le sigle correspondant au code de la base de données. Pour un échantillon provenant d'une autre instance de Collec-Science, le numéro correspond à l'UID de la base de données d'origine ;
si vous cochez rangement de l'échantillon dans un contenant, les colonnes container_parent_identifier, sample_column et sample_line seront rajoutées au fichier. Si vous avez également sélectionné l'importation d'un contenant, la colonne container_parent_identifier contiendra, dans les lignes d'exemple, l'identifiant métier du contenant d'exemple ajouté également dans le fichier ;
échantillon dérivé : la colonne sample_parent_identifier va être rajoutée, pour pouvoir indiquer l'identifiant métier du parent. Le parent doit soit exister au préalable, soit figurer plus haut dans le fichier ;
échantillon composé : si vous créez un échantillon composé, vous devrez indiquer dans la colonne composite_parents_identifier qui va être rajoutée au fichier l'ensemble des identifiants métiers des parents, séparés par une virgule ;
localisation GPS : les colonnes wgs84_x et wgs84_y seront rajoutées. Les coordonnées devront être indiquées sous forme numérique, avec le point comme séparateur décimal ;
<br>si l'échantillon possède déjà un identifiant de type <a href=".?query=tag:UUID" class="tag is-unresolved" target="_self" rel="noopener nofollow" data-href="#UUID">#UUID</a> (généré à partir d'une autre application ou d'une autre instance Collec-Science), vous pourrez l'indiquer ici. Une ligne d'exemple par type d'échantillon sélectionné sera rajoutée au fichier. Si des métadonnées sont obligatoires, vous retrouverez sur cette ligne d'exemple le terme obligatoire dans la colonne correspondante.<br>N'oubliez pas d'indiquer les identifiants secondaires si nécessaire (cf. <a data-href="#Rajouter des identifiants secondaires" href="gestion/générer-le-modèle-pour-les-importations-de-masse.html#Rajouter_des_identifiants_secondaires_0" class="internal-link" target="_self" rel="noopener nofollow">Rajouter des identifiants secondaires</a>, ci-dessous).<br><img alt="Pasted image 20260328161608.png" src="attachments/pasted-image-20260328161608.png" target="_self">Si vous souhaitez indiquer des identifiants secondaires, tant pour vos contenants que pour vos échantillons, vous pourrez les sélectionner dans la liste proposée dans identifiants secondaires. Une colonne sera créée avec comme entête le code de l'identifiant secondaire : dans l'exemple ci-dessus, si vous aviez sélectionné tag (pittag), la colonne tag aurait été rajoutée.Attention : seuls les identifiants secondaires qui possèdent un code seront affichés dans cette liste.

gestion/importer-des-échantillons-ou-des.description:
Pour éviter de devoir créer manuellement les échantillons ou les contenants, plusieurs mécanismes d'importation sont proposés :
un import de masse (<a data-href="L'import de masse" href="gestion/l'import-de-masse.html" class="internal-link" target="_self" rel="noopener nofollow">L'import de masse</a>), qui permet de créer des contenants ou des échantillons. Cet import est basé sur un fichier au format CSV, dont le format peut être généré par le logiciel (<a data-href="Générer le modèle pour les importations de masse" href="gestion/générer-le-modèle-pour-les-importations-de-masse.html" class="internal-link" target="_self" rel="noopener nofollow">Générer le modèle pour les importations de masse</a>). Cet import ne travaille qu'en mode "création" : il n'est pas possible de modifier des échantillons avec cette fonctionnalité ;
<br>un import d'échantillons externes (<a data-href="Importer des échantillons externes" href="gestion/importer-des-échantillons-externes.html" class="internal-link" target="_self" rel="noopener nofollow">Importer des échantillons externes</a>) : il s'agit d'une fonctionnalité qui permet, à partir d'un fichier généré depuis une autre instance de Collec-Science, d'intégrer dans sa propre instance ces échantillons. Cette fonctionnalité peut également être utilisée pour modifier des échantillons en dehors du logiciel ;
un import de contenants avec les objets qu'ils contiennent : cette fonctionnalité permet d'envoyer un contenant et les échantillons qui y sont stockés à une autre instance Collec-Science. Le fichier généré est au format JSON, qui permet de stocker des informations hiérarchisées.

gestion/l'import-de-masse.html.description:
L'import de masse permet de créer des contenants ou des échantillons à partir d'un fichier au format CSV.Le programme va travailler en deux phases. Dans un premier temps, il va vérifier la structure du fichier :
toutes les colonnes présentes doivent être attendues : si une colonne ne correspond pas à la liste des colonnes prévues, l'opération échouera ;
un certain nombre de contrôles de cohérence vont être réalisés, comme la vérification que le type d'échantillon existe bien dans la base de données, etc.
En cas de problème, le programme indiquera la ligne qui a généré une erreur, ainsi que le type d'erreur rencontrée.Si les contrôles sont corrects, l'importation va être lancée. Le programme va traiter les lignes les unes après les autres. Il va également être capable de réaliser des opérations particulières :
vous pourrez indiquer le nom d'un contenant où ranger l'objet que vous souhaitez créer. Le programme pourra ranger l'objet en cours de traitement dans un contenant qui aurait été déclaré précédemment dans le fichier ;
vous pourrez également définir le parent d'un échantillon, sous réserve que celui-ci existe au préalable dans la base de données ou s'il a été défini précédemment dans le fichier. Cela fonctionne également pour les échantillons composés.
Même si le logiciel est capable de le gérer, évitez de saisir dans la même ligne un contenant et un échantillon (dans ce cas, l'échantillon sera "déplacé" dans le contenant créé). Il vaut mieux prévoir une ligne pour le contenant, puis une ligne pour l'échantillon.Une fois l'importation achevée, le programme va afficher les UID mini et maxi des objets créés : notez ces informations, elles pourront vous être utiles pour retrouver vos contenants ou vos échantillons, particulièrement si vous vous rendez compte d'une erreur et que vous avez besoin de les supprimer pour les réimporter.Le logiciel préconisé est LibreOffice (<a rel="noopener nofollow" class="external-link is-unresolved" href="https://fr.libreoffice.org/" target="_self">https://fr.libreoffice.org/</a>) : Microsoft Excel a tendance à modifier des caractères (des guillemets, par exemple) qui pourraient vous poser des problèmes par la suite ou à utiliser des encodages des caractères susceptibles de perturber l'importation.Au moment d'enregistrer votre fichier (Fichier &gt; Enregistrer sous...), sélectionnez le type (en bas à droite) Texte CSV (.csv), et cochez Éditer les paramètres du filtre. Renseignez alors les paramètres suivants :
jeu de caractères : Unicode (UTF-8)
Séparateur de champ : virgule (la tabulation ou le point-virgule sont également acceptés)
<br><img alt="Pasted image 20260324101905.png" src="attachments/pasted-image-20260324101905.png" target="_self">À partir de la version v26.1.0, le logiciel intègre un module qui vous permet de générer un modèle de fichier qui sera configuré en fonction de ce que vous voulez importer. Il tiendra compte de la collection, des types d'échantillons à créer et des métadonnées associées, des identifiants secondaires, etc.<br>Pour plus d'informations : <a data-href="Générer le modèle pour les importations de masse" href="gestion/générer-le-modèle-pour-les-importations-de-masse.html" class="internal-link" target="_self" rel="noopener nofollow">Générer le modèle pour les importations de masse</a>.À ces informations, vous pourrez rajouter les métadonnées avec une colonne pour chaque type de métadonnée. Le nom des colonnes correspondantes doit être sous la forme md_*nom_metadonnee***. Le programme reconstituera le format initial (format JSON). Si vous souhaitez fournir les métadonnées directement sous la forme JSON (par exemple : {"taxon":"Alosa alosa"}), utilisez la colonne sample_metadata_json. Néanmoins cette approche est déconseillée, en raison des difficultés de codage qu'elle peut comporter.Si vous souhaitez rajouter des identifiants complémentaires, tant pour les contenants que pour les échantillons, ajoutez une colonne par type d'identifiant complémentaire. Le nom de la colonne doit impérativement être le code de l'identifiant (et pas son nom).Lorsque vous voulez importer un fichier, (Imports/Exports &gt; Import de masse), le logiciel vous demande de sélectionner le fichier et de préciser certains paramètres : <br><img alt="Pasted image 20260324102645.png" src="attachments/pasted-image-20260324102645.png" target="_self">
séparateur : vous pouvez indiquer la virgule, le point-virgule ou la tabulation. Vérifiez que le séparateur soit cohérent avec ce que vous avez indiqué lorsque vous avez généré le fichier.
Encodage du fichier : vous pouvez indiquer soit UTF-8 (format par défaut, conseillé) ou ISO-8859-x, format natif utilisé par les logiciels Microsoft. Dans ce second cas, les données seront réencodées avant traitement.
Rechercher les échantillons parents uniquement dans la collection des enfants : si vous positionnez ce paramètre à oui, les parents doivent impérativement appartenir à la même collection que les enfants. C'est un paramètre qui peut être utile si des échantillons portent le même nom dans des collections différentes.
Le programme va lancer un certain nombre de vérifications :
l'encodage du fichier indiqué va être comparé à celui qui semble avoir été utilisé pour générer le fichier ;
le nom des colonnes va être vérifié. Si une colonne n'appartient pas à celles qui sont attendues, une erreur est générée ;
les noms des types d'échantillons, types de contenants, etc. doivent exister dans la base de données ;
la collection de destination doit faire partie des collections pour lesquelles l'utilisateur dispose des droits adéquats ;
l'identifiant métier de l'échantillon ne doit pas exister dans la collection si celle-ci est paramétrée pour interdire les doublons d'identifiants métiers ;
le format des dates doit être cohérent. Le logiciel attend des formats de type "français", c'est à dire sous la forme jj/mm/aaaa ;
les métadonnées indiquées doivent exister pour le type d'échantillon considéré ;
les champs attendus comme devant être numériques ;
si un mouvement d'entrée dans un contenant est prévu, le programme va s'assurer que l'emplacement indiqué (ligne/colonne) ne soit pas plein ;
enfin, les lignes sans identifiant métier, soit pour un contenant, soit pour un échantillon, sont signalées.
En cas d'anomalie détectée, le programme va afficher la liste des erreurs, en précisant le numéro de la ligne concerné :<br><img alt="Pasted image 20260324104920.png" src="attachments/pasted-image-20260324104920.png" target="_self">Vous devrez corriger votre fichier et reprendre la procédure dès le début.Si les contrôles sont corrects, vous pourrez déclencher l'importation. Le programme va toutefois réaliser quelques contrôles complémentaires :
les parents doivent exister dans la base de données avant l'importation, ou figurer plus haut dans le fichier d'import ;
les contenants doivent également exister préalablement ou figurer plus haut dans le fichier d'importation.
Si une erreur survient, l'importation échouera dans sa globalité : aucun échantillon ou contenant ne sera créé, c'est du "tout ou rien". Le programme affichera alors une erreur du type :<br><img alt="Pasted image 20260324105515.png" src="attachments/pasted-image-20260324105515.png" target="_self">L'importation devra être recommencée à zéro.L'importation sera réalisée ainsi :
si la colonne sample_identifier est renseignée, l'échantillon sera créé ;
si la colonne container_identifier est renseignée, le contenant sera créé ;
si la colonne container_parent_identifier (ou container_parent_uid, dans le cas où le contenant existe au préalable et son UID est connu), un mouvement d'entrée sera généré ;
si les colonnes sample_identifier et container_identifier sont remplies sur la même ligne, l'échantillon sera rangé automatiquement dans le contenant figurant dans la même ligne. Toutefois, cette approche est déconseillée : il vaut mieux disposer d'une ligne différente pour les contenants et les échantillons, sachant que les mouvements d'entrée seront alors créés si la colonne container_parent_identifier est renseigné.
Si tout se passe bien, le programme affiche alors les UID minimum et maximum qui ont été générés :<br><img alt="Pasted image 20260324105732.png" src="attachments/pasted-image-20260324105732.png" target="_self">Notez bien ces informations : si vous avez besoin de retrouver les objets que vous venez de créer, ce sera bien plus facile avec celles-ci.Si vous ne les avez pas notées, vous pourrez toutefois les retrouver (ou les faire retrouver). Elles sont enregistrées dans les logs applicatives, consultables par un administrateur depuis le menu Administration &gt; Logs. Voici un exemple des traces qui ont été enregistrées et qui correspondent à l'exemple précédent :<br><img alt="Pasted image 20260324110153.png" src="attachments/pasted-image-20260324110153.png" target="_self">
Deux mouvements ont également été générés pendant cette importation.

gestion/la-liste-des-échantillons.html.description:
La liste des échantillons est disponible à deux endroits : soit depuis la page de recherche des échantillons (<a data-href="Chercher les échantillons" href="gestion/chercher-les-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">Chercher les échantillons</a>), soit depuis le détail d'un échantillon, dans l'onglet Échantillons dérivés.La liste est composée de trois parties :<br><img alt="Pasted image 20260224111947.png" src="attachments/pasted-image-20260224111947.png" target="_self">
au dessus du tableau, vous avez la possibilité de générer des étiquettes pour les échantillons sélectionnés ou créer des fichiers au format CSV ;
le tableau comprend la liste des échantillons ;
sous le tableau, si vous disposez du droit collection, vous aurez la possibilité de réaliser des opérations globales de modification des échantillons.
Vous pouvez sélectionner les colonnes que vous souhaitez afficher : <br><img alt="Pasted image 20260224112433.png" src="attachments/pasted-image-20260224112433.png" target="_self">Il suffit de sélectionner celles qui vous intéressent.Le moteur d'affichage dispose également de deux boutons qui vous permettront de récupérer le contenu de la liste au format CSV, ou de le copier pour le coller dans une autre application.Par défaut, les métadonnées sont toutes affichées. Vous avez la possibilité de n'en afficher qu'une seule. Pour cela, dans les critères de recherche :
positionnez-vous dans l'onglet Type et métadonnées ;
sélectionnez la métadonnée que vous voulez afficher dans la zone N'afficher qu'une métadonnée ;
relancez la recherche.
Au dessus du tableau, à droite, vous disposez d'une zone Rechercher qui vous permet de réaliser une recherche plein texte dans l'ensemble du tableau. Toutefois, vous pourriez souhaiter faire une recherche dans une seule colonne : il faut alors changer le mode d'affichage du tableau. Pour cela :
dans la partie basse du cartouche de recherche des échantillons, cliquez sur la case Activer la recherche par colonne ;<br>
<img alt="Pasted image 20260224113151.png" src="attachments/pasted-image-20260224113151.png" target="_self">
relancez la recherche : les entêtes de chaque colonne deviennent maintenant des zones de recherche, qui fonctionneront uniquement pour la colonne considérée.
<br><img alt="Pasted image 20260224113319.png" src="attachments/pasted-image-20260224113319.png" target="_self">Trois fonctionnalités sont disponibles pour tous les utilisateurs : l'impression d'étiquettes ;
la génération d'un fichier utilisable avec un logiciel tiers pour imprimer les étiquettes ;
la génération d'un fichier d'export, au format CSV, qui est utilisable pour modifier les échantillons en dehors du logiciel ou pour les transmettre à une autre instance de Collec-Science.
Pour que ces opérations puissent être lancées, vous devrez auparavant sélectionner les échantillons concernés. Vous pouvez tous les sélectionner (ou les désélectionner) en utilisant indifféremment la case Tout cocher ou celle qui est dans l'entête du tableau, en première colonne.Sélectionnez le modèle d'étiquettes que vous souhaitez utiliser, puis cliquez sur le bouton Étiquettes. Un nouvel onglet s'ouvrira dans votre navigateur, avec les étiquettes prêtes à être imprimées.Les étiquettes sont conçues pour être imprimées avec des imprimantes à rouleaux : chaque étiquette est séparée par un saut de page, qui correspond à une nouvelle étiquette avec ces imprimantes.<br>Si vous ne choisissez pas de modèle d'étiquettes, mais que ce modèle a été associé avec le premier type d'échantillons de la liste (cf. <a data-href="Les types d'échantillons" href="parametres/les-types-d'échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">Les types d'échantillons</a>), c'est ce modèle qui sera utilisé pour l'ensemble des échantillons sélectionnés.<br>Pour plus d'informations sur la création des modèles d'étiquettes, consultez la page <a data-href="Créer ou modifier un modèle d’étiquettes" href="parametres/créer-ou-modifier-un-modèle-d’étiquettes.html" class="internal-link" target="_self" rel="noopener nofollow">Créer ou modifier un modèle d’étiquettes</a>.Si vous souhaitez utiliser un logiciel tiers pour imprimer vos étiquettes, notamment pour pouvoir imprimer des planches d'étiquettes, vous pouvez déclencher l'export d'un fichier dédié au format CSV en cliquant sur le bouton Fichier CSV pour impression externe. Le fichier généré aura comme nom printlabel.csv.Le fichier d'export que vous pouvez créer en cliquant sur le bouton Export vers une autre base peut être utilisé pour deux usages différents :
vous pourrez ouvrir ce fichier (au format CSV) avec LibreOffice (évitez Excel, qui pose plus de problèmes de compatibilité), modifier le contenu des informations, puis les réimporter à partir du menu Imports/Exports &gt; Import d'échantillons externes. C'est le moyen le plus efficace pour modifier une série d'échantillons, rajouter des informations, etc.
vous pouvez transmettre le fichier généré à un autre organisme utilisant Collec-Science : il leur suffira d'utiliser la fonction disponible à partir du menu Imports/Exports &gt; Import d'échantillons externes pour les importer directement dans leur instance.
<br>Pour plus d'informations sur la fonction d'import externe, consultez la page <a data-href="Importer des échantillons externes" href="gestion/importer-des-échantillons-externes.html" class="internal-link" target="_self" rel="noopener nofollow">Importer des échantillons externes</a>.Si vous disposez du droit collection, vous pourrez réaliser des opérations globales sur les échantillons sélectionnés, sans avoir à les traiter un par un.<br>Pour plus d'informations sur ces opérations, consultez la page <a data-href="Les opérations globales sur les échantillons" href="objets/les-opérations-globales-sur-les-échantillons.html" class="internal-link" target="_self" rel="noopener nofollow">Les opérations globales sur les échantillons</a>

gestion/prêter-un-ou-plusieurs-échantill.description:
Il est possible de suivre le prêt d'échantillons auprès de laboratoires tiers, avec une fonction dédiée. Le prêt peut concerner soit un échantillon unique, soit un ensemble d'échantillons, par exemple une boite de tubes.Les objets prêtés (contenants ou échantillons) prennent le statut "prêté". Lors du prêt, l'emprunteur doit être désigné, et une date de retour prévue peut être positionnée.Au retour des échantillons ou des contenants, les objets reviennent au statut "normal".Le prêt ne fonctionne que pour des échantillons "complets". Il n'est pas possible de ne prêter qu'une partie d'un échantillon (en sous-échantillonnage) : dans ce cas de figure, il faut d'abord créer un échantillon dérivé contenant la partie de l'échantillon principal. C'est l'échantillon dérivé, entier (mais partie de l'échantillon principal), qui sera prêté.Depuis le menu de paramètres, choisissez Emprunteurs. À partir de la liste, vous pouvez soit créer un nouvel emprunteur, soit consulter les échantillons ou les contenants qui lui ont été prêtés. Depuis la liste des échantillons ou des contenants, vous pouvez prêter directement des objets. Si vous prêtez un contenant, l'ensemble des échantillons ou des contenants qu'il contient sera également marqué comme prêté. Chaque échantillon ou contenant pourra être traité indépendamment des autres, c'est à dire avoir une date de retour différente.Il est également possible de prêter un objet depuis son détail, dans l'onglet Événements/prêts.Si vous exportez un contenant avec ses échantillons, vous pouvez générer un fichier qui pourra être importé dans l'instance Collec-Science de votre emprunteur.Pour cela, depuis le menu Objets &gt; Contenants, sélectionnez le ou les contenants concernés, puis cliquez sur le bouton "Export avec objets inclus". Un fichier au format JSON sera généré, que vous pourrez transmettre à votre emprunteur.Celui-ci pourra importer le contenant et les échantillons associés dans sa base de données, à partir du menu Imports/Exports &gt; Imports de contenants externes.
Au moment de l'importation, un mouvement d'entrée va être généré pour tous les échantillons présents dans le contenant.La génération de ce fichier ne dispense pas de réaliser l'opération de prêt proprement dite.Une fois que l'emprunteur aura rendu ses échantillons, vous pouvez les réintégrer dans le logiciel.Deux approches sont possibles : dans le détail de l'échantillon, puis dans le détail du prêt, renseignez la date de retour réelle : le statut sera positionné automatiquement à "État normal" au moment de l'enregistrement ;
créez un mouvement d'entrée de l'objet, soit global, soit objet par objet : le statut sera positionné automatiquement à "État normal", la date de retour du prêt sera également renseignée à la date courante.

objets/les-opérations-globales-sur-les-é.description:
À partir de la liste des échantillons, il est possible de déclencher diverses opérations sur les échantillons sélectionnés.Pour pouvoir avoir accès à ces fonctionnalités, l'utilisateur doit disposer du droit collection, qui permet de manipuler rapidement l'ensemble des échantillons d'une collection.Certaines opérations imposent qu'une collection soit sélectionnée dans les paramètres de recherche des échantillons. Dans le cas contraire, les opérations considérées ne sont pas accessibles.Les opérations vont modifier individuellement les échantillons, et jamais de façon groupée. Elles sont l'équivalent d'une modification individuelle de chaque échantillon, il ne sera pas possible d'annuler collectivement une opération. Ce sont des actions très structurantes : vérifiez bien ce que vous faites avant de les valider !Avant de lancer une opération, pensez à cocher les échantillons concernés. Vous pouvez sélectionner (ou désélectionner) tous les échantillons en cliquant sur la case Tout cocher ou dans la première colonne de l'entête du tableau.<img alt="Pasted image 20260205104846.png" src="attachments/pasted-image-20260205104846.png" target="_self">L'opération va permettre d'indiquer un nouveau responsable, il suffit de le sélectionner dans la liste :<br><img alt="Pasted image 20260205105352.png" src="attachments/pasted-image-20260205105352.png" target="_self">Vous pouvez créer un événement pour chaque échantillon concerné, en indiquant les informations nécessaires :<br><img alt="Pasted image 20260205105521.png" src="attachments/pasted-image-20260205105521.png" target="_self">
Indiquez soit la date d'échéance, si c'est un événement programmé, soit la date de réalisation. Chaque échantillon sélectionné sera doté d'un événement chacun, qui pourra être manipulé indépendamment des autres.Vous pourrez manipuler collectivement les événements créés depuis la liste des événements (menu Objets &gt; Événements).L'opération de prêt va modifier de façon importante les échantillons concernés :
le statut va passer à "Objet prêté" ;
un mouvement de sortie va être généré automatiquement.
Vous devrez renseigner l'emprunteur, la date du prêt et la date de retour escomptée, ce qui vous permettra de retrouver les échantillons prêtés soit depuis la liste des emprunteurs, soit depuis l'interface de recherche, en sélectionnant le statut Objet prêté.<br><img alt="Pasted image 20260205110134.png" src="attachments/pasted-image-20260205110134.png" target="_self">Cette opération va générer un mouvement de sortie. Aucune information ne peut être indiquée ici.<br>Cette opération impose qu'une collection soit sélectionnée pour qu'elle puisse être exécutée. Consultez la page <a data-href="Les exports par lots" href="gestion/les-exports-par-lots.html" class="internal-link" target="_self" rel="noopener nofollow">Les exports par lots</a> pour plus d'informations.Vous pouvez indiquer le pays de collecte, utilisé dans le cadre du protocole de Nagoya, en le sélectionnant dans la liste officielle des pays :<br><img alt="Pasted image 20260205111115.png" src="attachments/pasted-image-20260205111115.png" target="_self">Sélectionnez la campagne de prélèvement pour y rattacher les échantillons : <br><img alt="Pasted image 20260205154006.png" src="attachments/pasted-image-20260205154006.png" target="_self"><br>La liste des statuts est fixe, et ne peut être modifiée (seuls les libellés peuvent être adaptés). Les statuts sont identiques pour les échantillons ou les <a href=".?query=tag:contenants" class="tag is-unresolved" target="_self" rel="noopener nofollow" data-href="#contenants">#contenants</a> . Les <a href=".?query=tag:statuts" class="tag is-unresolved" target="_self" rel="noopener nofollow" data-href="#statuts">#statuts</a> en vigueur sont :
État normal : tout échantillon stocké localement ;
objet pré-réservé pour usage ultérieur : cela concerne peu les échantillons, mais est surtout utilisé pour les contenants ;
objet détruit : cela concerne des échantillons dont on veut conserver la trace, mais qui n'existent plus ;
HS - vide - non conforme : c'est une variante du statut précédent ;
objet perdu : objet dont on a perdu la trace ;
objet prêté : normalement, ce statut est géré automatiquement par le logiciel quand on prête un échantillon.
<br><img alt="Pasted image 20260205154103.png" src="attachments/pasted-image-20260205154103.png" target="_self">Attention : après modification du statut, les échantillons n'apparaîtront plus par défaut dans la liste des échantillons, sauf si on modifie les critères de recherche en désactivant "État normal" ou en sélectionnant un statut particulier.<br><img alt="Pasted image 20260205154811.png" src="attachments/pasted-image-20260205154811.png" target="_self"><br><img alt="Pasted image 20260312114654.png" src="attachments/pasted-image-20260312114654.png" target="_self">Vous pouvez changer le type d'échantillon des échantillons sélectionnés en une seule opération. Avant de lancer l'opération, assurez-vous que le nouveau type d'échantillon est compatible avec les métadonnées associées avec l'ancien type, sinon vous risquez de perdre des informations.Si l'interface proposé est identique à celui utilisé pour la création d'un mouvement, il doit être manipulé avec précaution, notamment si vous voulez indiquer un numéro de ligne et de colonne. Dans ce cas de figure, les échantillons seront tous rangés au même endroit.<br><img alt="Pasted image 20260205155019.png" src="attachments/pasted-image-20260205155019.png" target="_self">L'utilisateur qui réalise l'opération doit disposer des droits à la fois sur la collection d'origine et sur la nouvelle collection.<br><img alt="Pasted image 20260205155229.png" src="attachments/pasted-image-20260205155229.png" target="_self">Cela permet a posteriori d'affecter un parent à un ou plusieurs échantillons "enfants". <br><img alt="Pasted image 20260205155428.png" src="attachments/pasted-image-20260205155428.png" target="_self">Dans la zone Recherchez le parent, indiquez l'UID ou l'identifiant métier, puis cliquez sur la loupe pour le rechercher. Le parent (ou les parents potentiels, le logiciel réalise une recherche "plein texte") est alors affiché dans la liste Parent à affecter.Avec ce module, faites attention à ne pas créer une boucle (un parent qui contiendrait un enfant qui lui-même contiendrait le parent) : vous risqueriez de faire planter le serveur en saturant toutes les ressources !Un échantillon composé est un échantillon qui contient un sous-échantillonnage de plusieurs autres échantillons, par exemple pour réaliser une analyse globale.<br><img alt="Pasted image 20260205155936.png" src="attachments/pasted-image-20260205155936.png" target="_self">
Vous devrez indiquer :
la quantité de sous-échantillonnage que vous retirez de chaque parent. Dans ce contexte précis, la quantité retirée de chaque parent est identique : si vous souhaitez des quantités différentes, vous devrez soit réaliser des modifications depuis le détail de l'échantillon qui sera créé, soit créer les sous-échantillonnages un par un ;
l'identifiant métier de l'échantillon créé ;
sa collection d'affectation ;
le type d'échantillon créé.
Vous avez également la possibilité de rattacher des échantillons parents à un échantillon composé déjà existant. Dans ce cas de figure, indiquez son UID ou son identifiant métier puis cliquez sur la loupe pour le retrouver dans la base de données.Par défaut, la quantité de l'échantillon créé est la somme des quantités prélevées de chaque échantillon parent. Toutefois, dans certains cas de figure, l'échantillon que vous allez créer peut être plus volumineux (ajout d'un solvant, par exemple). Si vous créez l'échantillon composé ex nihilo, vous avez alors la possibilité d'indiquer la quantité réelle qu'il contiendra.La corbeille fonctionne comme pour les logiciels de messagerie : si vous mettez un message dans celle-ci, celui-ci n'est plus visible, mais n'est pas encore supprimé. De la même manière, vous pouvez mettre de côté un échantillon avant de le supprimer.Si un échantillon a été mis à la corbeille, il ne sera plus visible, sauf si vous changez les paramètres de recherche :<br><img alt="Pasted image 20260205160828.png" src="attachments/pasted-image-20260205160828.png" target="_self">Cette opération supprime de manière définitive les échantillons sélectionnés. Si vous hésitez, placez-les plutôt dans la corbeille...La suppression d'un échantillon ne fonctionnera pas si des échantillons dérivés ont été créés à partir de celui-ci.Cette fonction permet de faire un grand ménage : il va supprimer tous les échantillons et tous les échantillons enfants (dérivés) qui lui sont rattachés, et ceci en cascade.Manipulez cette fonctionnalité avec précaution !Vous retrouverez ici le même interface qui permet de rattacher un document à un échantillon. Attention : le document sera dupliqué dans la base de données pour chaque échantillon de rattachement.<br><img alt="Pasted image 20260205161336.png" src="attachments/pasted-image-20260205161336.png" target="_self">Vous pouvez indiquer la date de création et une description.

parametres/créer-ou-modifier-un-modèle-d.description:
Les étiquettes sont composées de deux parties : un ou deux codes lisibles avec un lecteur optique, et du texte. Il est également possible d'insérer un logo.Les codes optiques peuvent être de deux types :
soit un QRCODE: celui-ci peut contenir : plusieurs informations, stockées au format JSON : il devra alors comprendre au minimum l'UID de l'objet et le code de la base de données ;
une seule information. Dans ce cas, on privilégiera l'identifiant de type UUID, qui garantit l'unicité de l'objet au niveau mondial, sauf si le QRCODE généré est trop grand. Il faudra alors stocker uniquement l'UID de l'échantillon ; soit un code-barre 1D au format EAN 128. Ce format est utilisé pour les supports ronds (tubes), qui rendent la lecture optique 2D difficile. Dans ce cas, le code ne devrait contenir que l'UID de l'échantillon.
Les étiquettes sont créées en recourant au logiciel FOP, écrit en Java.Voici les opérations réalisées par l’application pour générer les étiquettes :
pour chaque objet concerné (des contenants ou des échantillons associés à un type de contenant, et si le type de contenant est rattaché à un modèle d’étiquettes), une image des codes optiques, ainsi que le logo, sont générés dans un dossier temporaire ;
dans ce dossier temporaire, un fichier au format XML est généré qui contient les informations à imprimer sur l’étiquette ;
un fichier au format XSL, qui contient les ordres de création de l’étiquette, est également créé dans le même dossier. Le contenu de ce fichier est issu d’un enregistrement provenant de la table label ;
le programme PHP fait appel à FOP pour générer, à partir du fichier XML et en utilisant le fichier XSL, un fichier PDF. Une page du fichier correspond à une étiquette (mécanisme utilisé par les imprimantes à étiquettes pour les séparer).
La configuration du modèle d’étiquettes revient à définir à la fois le contenu des informations qui seront insérées dans les codes optiques et la forme que prendra l’étiquette, c’est à dire les informations qui seront imprimées, le format, etc. Cette forme reprend la syntaxe XSL comprise par FOP.Le logiciel est livré avec une étiquette type : il est préférable de dupliquer cette étiquette plutôt que de partir d'une "page blanche".Pour cela, depuis la liste des modèles d'étiquettes, cliquez sur le bouton Dupliquer à partir du modèle livré : <img alt="Pasted image 20251007154048.png" src="attachments/pasted-image-20251007154048.png" target="_self">
Pour mettre au point le modèle, nous vous conseillons d'utiliser deux navigateurs : l'un pour ajuster les différents paramètres, et l'autre pour visualiser le contenu en générant manuellement les étiquettes.Lors de la génération des étiquettes, si rien n'est produit et que le logiciel vous indique une erreur, c'est probablement qu'une balise, dans le code de description de l'étiquette, n'est pas fermée. Malheureusement, les messages d'erreur détaillés ne peuvent être consultés qu'avec un accès au serveur, en consultant les logs du serveur web.Techniquement, la commande suivante est lancée par l'application :/usr/bin/fop -xsl /var/www/collecApp/collec-science/writable/temp/1.xsl -xml /var/www/collecApp/collec-science/writable/temp/b98ff1340b2e.xml -pdf /var/www/collecApp/collec-science/writable/temp/b98ff1340b2e.pdf le fichier 1.xsl contient la définition de l'étiquette (champ Transformation XSL). Le nom du fichier correspond à l'identifiant du modèle d'étiquette dans la base de données. Ce fichier est détruit automatiquement une fois que l'étiquette a été générée
le fichier xml est conservé dans le dossier temporaire du serveur (writable/temp/). Le nom du fichier est généré automatiquement
le fichier pdf contient les étiquettes prêtes à être imprimées.
Si vous souhaitez mettre au point un modèle d'étiquette en dehors du logiciel (et notamment le contenu du champ Transformation XSL), vous devrez :
dans les paramètres de l'application, (Administration &gt; Paramètres de l'application), positionnez la valeur labelDebugMode à 1
lancez la génération d'une étiquette
depuis le serveur web, récupérez les fichiers présents dans le dossier /var/www/collecApp/collec-science/writable/temp, et notamment le fichier xml (les données à insérer), le fichier xsl (le modèle de l'étiquette) et les fichiers png (les codes optiques générés et le logo) adaptez la commande fop à votre environnement et exécutez-là depuis un terminal. <br>Vous pouvez récupérer le programme fop depuis ce site : <a rel="noopener nofollow" class="external-link is-unresolved" href="https://xmlgraphics.apache.org/fop/download.html" target="_self">https://xmlgraphics.apache.org/fop/download.html</a>. Fop est également disponible dans les dépôts des principales distributions Linux.Cette manière de faire vous permettra de visualiser plus facilement les messages d'erreur, suffisamment détaillés pour comprendre où le problème se pose.Une fois votre étiquette mise au point, n'oubliez-pas de repositionner le paramètre labelDebugMode à 0.Le logiciel vous permet de générer un ou deux codes optiques, au format :
QRcode : c'est un format de code barre normalisé en deux dimensions, qui permet de stocker jusqu’à 2000 caractères en 8 bits. Les QRcodes peuvent être lus facilement avec l'application depuis une tablette numérique, voire un smartphone.
EAN128 : code barre 1D qui encode jusqu'à 128 caractères alpha-numériques. Compte-tenu de l'extrême densité des informations, il est difficile de lire un code de ce type avec une tablette, le recours à des lecteurs optiques (douchettes) est quasi-indispensable. Ce type de code est par contre adapté aux supports arrondis (tubes).
À noter que le module de lecture des codes-barres dans l'application qui utilise la caméra d'une tablette ou d'un smartphone, est actuellement incapable de lire autre chose qu'un QRCode.Le contenu du QRcode peut être formaté selon deux méthodes : soit le contenu contient plusieurs informations différentes, encodées en JSON : c'est le format initial (historique) utilisé par l'application
soit le contenu ne contient qu'une information, avec ou non un radical (pour générer des url) : on privilégiera alors soit l'intégration de l'UUID, soit l'identifiant de la base de données d'origine (qui est généré automatiquement s'il n'existe pas au préalable).
Pour un contenu multiple, au format JSON :
champs obligatoires : autres champs utilisables :
À noter que plus vous utilisez d'informations, plus le code généré sera dense, et nécessitera une grande taille pour pouvoir rester lisible.
Champs utilisables dans le QRCODE à contenu unique :
Il est conseillé d'utiliser dans ce cas de figure de préférence le code UUID, qui garantit l'unicité du numéro de l'échantillon ou de l'objet au niveau mondial.Pour des raisons de lecture optique, il est fortement conseillé de n'insérer que le numéro uid de l'échantillon, ou dbuid_origin.La syntaxe particulière du fichier XSL ne doit être modifiée qu’en conservant la version initiale (recopie dans un bloc-notes, par exemple), pour éviter de perdre une configuration opérationnelle suite à un mauvais paramétrage.Voici la description du contenu du fichier et les zones modifiables. Nous allons prendre comme exemple cette étiquette :<br>
<img alt="Pasted image 20251005192821.png" src="home/equinton/web/userdocs/attachments/pasted-image-20251005192821.html" referrerpolicy="no-referrer" target="_self">Elle est organisée ainsi : La partie haute est un tableau, composé d'une ligne et de deux colonnes : la première colonne contient un logo, un texte, puis sur la ligne inférieur, le code du labo dans l'application et l'uid de l'échantillon. La troisième ligne contient l'identifiant métier (id) de l'échantillon
la seconde colonne contient le QRCODE)
La partie basse contient un code EAN128 centré, puis sur la ligne inférieure, le risque CLP.
Elle permet de modifier la taille de l’étiquette (largeur et hauteur maximale). Vous ne devriez changer que les attributs page-height et page-width. Pour les marges (attributs margin-), soyez prudents et vérifiez notamment que les QRcodes ne soient pas rognés à cause de marges insuffisantes.&lt;?xml version="1.0" encoding="utf-8"?&gt;
&lt;xsl:stylesheet version="1.0" xmlns:xsl="http://www.w3.org/1999/XSL/Transform" xmlns:fo="http://www.w3.org/1999/XSL/Format"&gt; &lt;xsl:output method="xml" indent="yes"/&gt; &lt;xsl:template match="objects"&gt; &lt;fo:root&gt; &lt;fo:layout-master-set&gt; &lt;fo:simple-page-master master-name="label" page-height="5cm" page-width="10cm" margin-left="0.5cm" margin-top="0.5cm" margin-bottom="0cm" margin-right="0.5cm"&gt; &lt;fo:region-body/&gt; &lt;/fo:simple-page-master&gt; &lt;/fo:layout-master-set&gt; &lt;fo:page-sequence master-reference="label"&gt; &lt;fo:flow flow-name="xsl-region-body"&gt; &lt;fo:block&gt; &lt;xsl:apply-templates select="object" /&gt; &lt;/fo:block&gt; &lt;/fo:flow&gt; &lt;/fo:page-sequence&gt; &lt;/fo:root&gt; &lt;/xsl:template&gt;
Le contenu proprement dit de l'étiquette est décrit dans match="object". Nous allons commencer par déclarer le tableau (table), avec la largeur de chaque colonne.	&lt;xsl:template match="object"&gt; &lt;fo:table table-layout="fixed" border-collapse="collapse" border-style="none" width="9cm" keep-together.within-page="always"&gt; &lt;fo:table-column column-width="6cm"/&gt; &lt;fo:table-column column-width="3cm" /&gt;
Nous allons maintenant déclarer le contenu du tableau, en commençant par déclarer une ligne, puis la première colonne (table-cell): &lt;fo:table-body border-style="none" &gt; &lt;fo:table-row&gt; &lt;fo:table-cell&gt; &lt;fo:block&gt; &lt;fo:external-graphic&gt; &lt;xsl:attribute name="src"&gt; &lt;xsl:value-of select="concat(label_id,'-logo.png')"/&gt; &lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-height"&gt;scale-to-fit&lt;/xsl:attribute&gt; &lt;xsl:attribute name="height"&gt;1cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-width"&gt;1cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="scaling"&gt;uniform&lt;/xsl:attribute&gt; &lt;/fo:external-graphic&gt; &lt;fo:inline&gt; Labo Collec-Science&lt;/fo:inline&gt; &lt;/fo:block&gt; &lt;fo:block&gt;&lt;fo:inline font-weight="bold"&gt;&lt;xsl:value-of select="db"/&gt;:&lt;xsl:value-of select="uid"/&gt;&lt;/fo:inline&gt;&lt;/fo:block&gt; &lt;fo:block&gt;id:&lt;fo:inline font-weight="bold"&gt;&lt;xsl:value-of select="id"/&gt;&lt;/fo:inline&gt;&lt;/fo:block&gt; &lt;/fo:table-cell&gt;
Chaque ligne dans la cellule du tableau est définie dans un bloc (balises fo:block).
Le logo est déclaré dans un external-graphic, et le nom du fichier est généré à partir de l'identifiant de l'étiquette (label-id) associé à -logo.png. Divers attributs sont précisés pour définir les paramètres du graphique, ici la hauteur est fixée à 1cm.Le libellé Labo Collec-Science est rajouté à la suite du logo, en utilisant la balise inline. Divers attributs permettent d'indiquer soit des tailles de texte, soit du gras (ici, font-weight="bold").Les différentes informations de l'objet sont insérées dans l'étiquette en utilisant la balise : &lt;xsl:value-of select="db"/&gt; (pour le code de la base de données). Voici la liste des attributs utilisables :La seconde cellule (seconde colonne) est alors rajoutée : &lt;fo:table-cell&gt; &lt;fo:block&gt; &lt;fo:external-graphic&gt; &lt;xsl:attribute name="src"&gt; &lt;xsl:value-of select="concat(uid,'.png')" /&gt; &lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-height"&gt;scale-to-fit&lt;/xsl:attribute&gt; &lt;xsl:attribute name="height"&gt;2.5cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-width"&gt;2.5cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="scaling"&gt;uniform&lt;/xsl:attribute&gt; &lt;/fo:external-graphic&gt; &lt;/fo:block&gt; &lt;/fo:table-cell&gt; &lt;/fo:table-row&gt; &lt;/fo:table-body&gt; &lt;/fo:table&gt;
Ici, le QRcode est inséré (sous la forme d'un graphique dont le nom est l'UID de l'objet). La ligne est alors fermée (&lt;/fo:table-row&gt;), puis le tableau.La partie basse de l'étiquette est générée de la même manière, mais sans utiliser un tableau :	&lt;fo:block text-align="center"&gt; &lt;fo:external-graphic&gt; &lt;xsl:attribute name="src"&gt; &lt;xsl:value-of select="concat(uid,'-2.png')" /&gt; &lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-height"&gt;scale-to-fit&lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-width"&gt;9cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="height"&gt;1cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="scaling"&gt;uniform&lt;/xsl:attribute&gt; &lt;/fo:external-graphic&gt; &lt;/fo:block&gt; &lt;fo:block text-align="center"&gt; Risque:&lt;fo:inline font-weight="bold"&gt;&lt;xsl:value-of select="clp"/&gt;&lt;/fo:inline&gt; &lt;/fo:block&gt;
Le second code optique est identifié à partir de l'UID suivi de -2.Il ne reste plus qu'à fermer les balises et à indiquer au processeur fop de générer un saut de page : &lt;fo:block page-break-after="always"/&gt; &lt;/xsl:template&gt;
&lt;/xsl:stylesheet&gt;
<br>Pour aller plus loin dans la mise en page, vous pouvez consulter la <a data-tooltip-position="top" aria-label="https://xmlgraphics.apache.org/fop/fo.html" rel="noopener nofollow" class="external-link is-unresolved" href="https://xmlgraphics.apache.org/fop/fo.html" target="_self">documentation du projet FOP</a>, et pour le formatage du texte, <a data-tooltip-position="top" aria-label="https://www.w3.org/TR/xsl11" rel="noopener nofollow" class="external-link is-unresolved" href="https://www.w3.org/TR/xsl11" target="_self">celle concernant XSL</a>.&lt;?xml version="1.0" encoding="utf-8"?&gt;
&lt;xsl:stylesheet version="1.0" xmlns:xsl="http://www.w3.org/1999/XSL/Transform" xmlns:fo="http://www.w3.org/1999/XSL/Format"&gt; &lt;xsl:output method="xml" indent="yes"/&gt; &lt;xsl:template match="objects"&gt; &lt;fo:root&gt; &lt;fo:layout-master-set&gt; &lt;fo:simple-page-master master-name="label" page-height="5cm" page-width="10cm" margin-left="0.5cm" margin-top="0.5cm" margin-bottom="0cm" margin-right="0.5cm"&gt; &lt;fo:region-body/&gt; &lt;/fo:simple-page-master&gt; &lt;/fo:layout-master-set&gt; &lt;fo:page-sequence master-reference="label"&gt; &lt;fo:flow flow-name="xsl-region-body"&gt; &lt;fo:block&gt; &lt;xsl:apply-templates select="object" /&gt; &lt;/fo:block&gt; &lt;/fo:flow&gt; &lt;/fo:page-sequence&gt; &lt;/fo:root&gt; &lt;/xsl:template&gt; &lt;xsl:template match="object"&gt; &lt;fo:table table-layout="fixed" border-collapse="collapse" border-style="none" width="9cm" keep-together.within-page="always"&gt; &lt;fo:table-column column-width="6cm"/&gt; &lt;fo:table-column column-width="3cm" /&gt; &lt;fo:table-body border-style="none" &gt; &lt;fo:table-row&gt; &lt;fo:table-cell&gt; &lt;fo:block&gt; &lt;fo:external-graphic&gt; &lt;xsl:attribute name="src"&gt; &lt;xsl:value-of select="concat(label_id,'-logo.png')"/&gt; &lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-height"&gt;scale-to-fit&lt;/xsl:attribute&gt; &lt;xsl:attribute name="height"&gt;1cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="content-width"&gt;1cm&lt;/xsl:attribute&gt; &lt;xsl:attribute name="scaling"&gt;uniform&lt;/xsl:attribute&gt; &lt;/fo:external-graphic&gt; &lt;fo:inline&gt; Labo Collec-Science&lt;/fo:inline&gt; &lt;/fo:block&gt; &lt;fo:block&gt;&lt;fo:inline font-weight="bold"&gt;&lt;xsl:value-of select="db"/&gt;:&lt;xsl:value-of select="uid"/&gt;&lt;/fo:inline&gt;&lt;/fo:block&gt; &lt;fo:block&gt;id:&lt;fo:inline font-weight="bold"&gt;&lt;xsl:value-of select="id"/&gt;&lt;/fo:inline&gt;&lt;/fo:block&gt; &lt;/fo:table-cell&gt; &lt;fo:table-cell&gt; &lt;fo:block&gt; &lt;fo:exte